'use strict';
// Prepared actual-source pure operations; no storage, serialization or setup timed.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const lib=require('./moderation_spam_source.cjs');lib.independent('DIMA_SPAM_BENCH_READER_SHA256',__filename);
const names=['invitation','settings','rule_context','review_policy','marker'];
function pool(name){return Array.from({length:32},(_,i)=>{
 const context=Array.from({length:8},(_,j)=>({isBroadcaster:j===7,message:`case ${i} line ${j} `+(j===7&&i%2===0?['share your channel links','compartan sus canales','ſhare\u00a0channel','drop\nTwitch'][i%4]:'ordinary streaming discussion 😀 \ud800')}));
 const protection={enabled:i%5!==0,reviewAllMessages:i%3!==0,categories:i%7===0?[]:['spam','ads',`unknown-${i}`],thresholdPercent:80+i/8,exemptTags:i%4?['mod','editor','admin']:[]};
 const settings={settingsVersion:i,enabled:i%3!==0,spamProtection:protection,rules:[{id:`custom-${i}`,enabled:i%2===0}]};
 switch(name){case 'invitation':return {export:'broadcasterInvitedPromotion',args:[context]};case 'settings':return {export:'spamProtectionSettings',args:[settings]};case 'rule_context':return {export:'spamRuleForContext',args:[context,settings]};case 'review_policy':return i%2?{export:'spamReviewSource',args:[i%3===0,settings,['free','premium','pro'][i%3]]}:{export:'semanticPolicyActive',args:[settings,{settingsVersion:i,ruleID:i%4===0?'builtin-spam-protection':`custom-${i}`,reviewSource:i%4===0?'spam_continuous':'rule'}]};case 'marker':return {export:'chatterMarkerID',args:[`channel-${i}-😀\ud800`,`user-${31-i}-"\\\n\udc00`]};default:throw Error('unknown workload');}
 });}
const invoke=(api,c)=>api[c.export](...c.args);
function build(){const normal=lib.realm().api,vm=lib.realm({kind:'vm'}).api,workloads={};for(const name of names){const cases=pool(name);assert.equal(new Set(cases.map(c=>JSON.stringify(lib.encode(c.args)))).size,32);workloads[name]=cases.map(c=>{const value=invoke(normal,c),expected=lib.encode(value);assert.deepEqual(lib.encode(invoke(vm,c)),expected);return {export:c.export,args:lib.encode(c.args),result:{ok:true,value:expected}};});}return {format:1,workloads};}
function checksum(results){let h=2166136261;const add=n=>h=Math.imul(h^n,16777619)>>>0;function visit(v){switch(v.kind){case 'undefined':add(0);break;case 'hole':add(1);break;case 'null':add(2);break;case 'boolean':add(3);add(Number(v.value));break;case 'number':add(4);for(const b of Buffer.from(v.bits))add(b);break;case 'string':add(5);for(const u of v.utf16)add(u);add(65536);break;case 'array':add(6);add(v.items.length);for(const x of v.items)visit(x);break;case 'object':add(7);add(v.entries.length);for(const [key,x] of v.entries){for(const u of key)add(u);add(65536);visit(x);}break;case 'date':add(8);visit(v.milliseconds);break;default:throw Error('invalid checksum tag');}}for(const v of results){visit(v);add(65537);}return h;}
function bytes(){return JSON.stringify(build(),null,2)+'\n';}
function report(input){const data=JSON.parse(input);return {format:1,inputSha256:lib.sha(input),benchmarkSha256:lib.sha(fs.readFileSync(__filename)),loaderSha256:lib.sha(lib.read('tests/fixtures/moderation_spam_source.cjs')),advancedLoaderSha256:lib.sha(lib.read('tests/fixtures/moderation_advanced_source.cjs')),nodeSha256:lib.nodeSha,versions:process.versions,re2Runtime:lib.re2Runtime,sourcePins:lib.pins,transpiled:lib.compiled,poolChecksums:Object.fromEntries(names.map(n=>[n,checksum(data.workloads[n].map(c=>c.result.value))])),poolUniqueInputs:32};}
function input(){const file=process.env.DIMA_SPAM_BENCHMARK_FIXTURE;assert(file&&path.isAbsolute(file));const real=fs.realpathSync(file);lib.external(path.dirname(real));const input=fs.readFileSync(real,'utf8'),hash=lib.sha(input);assert(/^[a-f0-9]{64}$/.test(process.env.DIMA_SPAM_BENCHMARK_SHA256||''));assert.equal(hash,process.env.DIMA_SPAM_BENCHMARK_SHA256);assert.equal(input,bytes());return {data:JSON.parse(input),hash};}
function actor(name){assert(names.includes(name));const {data,hash}=input(),api=lib.realm().api,prepared=Object.fromEntries(names.map(n=>[n,pool(n)]));for(const n of names){assert.equal(data.workloads[n].length,32);for(let i=0;i<32;i++){assert.deepEqual(lib.encode(prepared[n][i].args),data.workloads[n][i].args);assert.deepEqual(lib.encode(invoke(api,prepared[n][i])),data.workloads[n][i].result.value);}}
 const rounds=Number(process.env.DIMA_SPAM_BENCH_ROUNDS||250);assert(Number.isSafeInteger(rounds)&&rounds>=1&&rounds<=500);const count=rounds*32,selected=prepared[name];for(let w=0;w<3;w++){const retained=new Array(count);let n=0;for(let i=0;i<rounds;i++)for(const c of selected)retained[n++]=invoke(api,c);assert.equal(n,count);}
 assert.equal(typeof global.gc,'function','requires --expose-gc');global.gc();const results=new Array(count);let n=0;const start=process.hrtime.bigint();for(let i=0;i<rounds;i++)for(const c of selected)results[n++]=invoke(api,c);const elapsed=process.hrtime.bigint()-start;const projected=results.map(lib.encode);for(let i=0;i<count;i++)assert.deepEqual(projected[i],data.workloads[name][i%32].result.value);return {format:1,actor:'node',workload:name,rounds,operations:count,warmups:3,warmupOperations:count*3,nanoseconds:elapsed.toString(),checksum:checksum(projected),inputSha256:hash,nodeSha256:lib.nodeSha,node:process.versions.node,abi:process.versions.modules,re2Runtime:lib.re2Runtime};}
const [mode,arg,...extra]=process.argv.slice(2);assert.equal(extra.length,0);
if(mode==='--write'){const dir=lib.external(arg);assert.deepEqual(fs.readdirSync(dir),[]);const input=bytes();fs.writeFileSync(path.join(dir,'input.json'),input,{flag:'wx'});fs.writeFileSync(path.join(dir,'source-report.json'),JSON.stringify(report(input),null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({inputSha256:lib.sha(input)}));}
else if(mode==='--actor')console.log(JSON.stringify(actor(arg)));
else if(mode==='--check'){const dir=lib.external(arg);const files=fs.readdirSync(dir);assert(files.includes('input.json')&&files.includes('source-report.json'));assert(files.every(f=>['input.json','source-report.json'].includes(f)||/^sample-(node|rust)-(invitation|settings|rule_context|review_policy|marker)-[1-7]\.json$/.test(f)));const input=fs.readFileSync(path.join(dir,'input.json'),'utf8');assert.equal(input,bytes());assert.deepEqual(JSON.parse(fs.readFileSync(path.join(dir,'source-report.json'))),report(input));const data=JSON.parse(input);for(const f of files.filter(f=>f.startsWith('sample-'))){const s=JSON.parse(fs.readFileSync(path.join(dir,f)));assert.equal(s.inputSha256,lib.sha(input));assert(names.includes(s.workload));assert.equal(s.operations,s.rounds*32);assert.equal(s.warmups,3);assert.equal(s.warmupOperations,s.operations*3);assert(/^[1-9][0-9]*$/.test(s.nanoseconds));assert.equal(s.checksum,checksum(Array.from({length:s.rounds},()=>data.workloads[s.workload].map(c=>c.result.value)).flat()));}console.log(JSON.stringify({checked:true,inputSha256:lib.sha(input)}));}
else throw Error('usage: --write DIR | --check DIR | --actor WORKLOAD');
